import assert from "node:assert/strict";
import { test } from "node:test";
import { correctedArmorSlots } from "../src/overlay/armor-slots-corrections.js";

/**
 * Pins real, confirmed-clean-transposition pairs from the checked-in
 * `armor-slots-corrections.json` (generated by `scripts/generate-armor-
 * slots-corrections.ts` against a real EBOOT — see that file and the
 * overlay module's doc comment for the full pairing + verification
 * methodology). Real bytes: raw `head[27]` ("Cephalos Helm" via the
 * index-drift correction) reads raw `slots=2`, but committed data expects
 * `1`; its paired `head[28]` ("Cephalos Cap") reads raw `slots=1` but
 * committed expects `2` — an exact swap.
 */
test("correctedArmorSlots swaps a confirmed transposed pair", () => {
  assert.equal(correctedArmorSlots("head", 27, 2), 1);
  assert.equal(correctedArmorSlots("head", 28, 1), 2);
});

test("correctedArmorSlots swaps a confirmed transposed waist pair", () => {
  // Real bytes: raw waist[28] ("Rathian Tasset") reads raw slots=1,
  // committed expects 2; paired waist[29] ("Rathian Coat") reads raw
  // slots=2, committed expects 1.
  assert.equal(correctedArmorSlots("waist", 28, 1), 2);
  assert.equal(correctedArmorSlots("waist", 29, 2), 1);
});

test("correctedArmorSlots falls back to the raw value for an unlisted raw index", () => {
  // Index 0 is the "dummy"/placeholder entry — never a confirmed pair.
  assert.equal(correctedArmorSlots("head", 0, 0), 0);
  // Genprey Helm (head[19]) has a known, separate slots mismatch that is
  // NOT one of the 8 confirmed-clean-transposition pairs (see
  // `armor-index-corrections.test.ts`) — must remain unmodified.
  assert.equal(correctedArmorSlots("head", 19, 0), 0);
});

test("correctedArmorSlots falls back to the raw value for slots with no known transpositions", () => {
  // chest/arm/leg have zero confirmed pairs — every raw index falls through.
  assert.equal(correctedArmorSlots("chest", 5, 3), 3);
  assert.equal(correctedArmorSlots("arm", 5, 3), 3);
  assert.equal(correctedArmorSlots("leg", 5, 3), 3);
});
